return {hdroom0501={id="hdroom0501",name="北大街",permission=1,mapHide="0",dsc="莺啼燕语报新年，马邑龙堆路几千。又是一年新春，南归的燕子啄起春泥，在屋檐下筑起新巢，几只黄莺飞上初透嫩绿的小草和柳梢。燕归来，莺语乱，街上人声喧闹，似是在歌咏春天的来到。",up="hdroom0547",down="hdroom0504",roomRoles={"bsnpc03"},roomItems={},roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0502={id="hdroom0502",name="大街口",permission=1,mapHide="0",dsc="爆竹声中一岁除，春风送暖入屠苏。新春的暖风吹进街口，街旁侧屋林立，每每间隔十步就挂有一排红灯笼，而街上行人不断，随意在繁闹的大街上徜徉着，人人心中都怀着对新春的期盼，脸上都洋溢着热情的笑容。",down="hdroom0507",left="hdroom0553",right="hdroom0503",roomRoles={"bsnpc25"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0503={id="hdroom0503",name="北内大街",permission=1,mapHide="0",dsc="半盏屠苏犹未举，灯前小草写桃符。新春已至，内大街一侧的小亭里随意地摆放着几幅刚写好的春联，春联上红纸黑墨写着几个行书大字。亭子里一位花甲老人正在木桌上舞文弄墨，一只毛笔挥得龙飞凤舞，而旁边的数个小童磨墨扶纸，拍手叫好。",left="hdroom0502",right="hdroom0504",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},aut