5",left="hdroom0518",right="hdroom0520",roomRoles={"bsnpc10"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={{type="equaltab",args={"311001",8}},{type="inroom",args={"hdroom0518","hdroom0519"}}}},autoResult1={{type="stop",args={}},{type="doc",args={"YEL连翘：先别乱逛啦。NOR"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0520={id="hdroom0520",name="平安东街",permission=1,mapHide="0",dsc="新年的第一个早晨，街道两旁嫩绿柳条初初抽芽，系上大红的缎带随着轻风飘飘摆摆。春日的阳光洒在地面上暖融融，大街上车水马龙，一家家老老少少走街串巷，在街上互道新春祝福，真可谓热闹非凡。",up="hdroom0513",down="hdroom0526",left="hdroom0519",right="hdroom0521",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0521={id="hdroom0521",name="浮云寺门",permission=1,mapHide="0",dsc="春节的浮云寺人山人海，狭小的寺门被前来祈福的香客堵得水泄不通。寺庙的外墙上，贴着一对新换的春联，右边的一幅写着：芳草春来依旧绿，左边的一幅写着：梅花到时自然红，遒劲恢宏的笔法令香客们赞不绝口。",left="hdroom0520",right="hdroom0522",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={{type="equaltab",args={"311001",3}},{type="inroom",args={"hdroom0520","hdroom0521"}}}},autoResult1={{type="stop",args={}},{type="doc",args={"YEL连翘：先别乱逛啦。NOR"}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"311001",5}},{type="inroom",args={"h